// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;

    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        Probe p = new Probe();
        vm.deal(address(p), depositAmount);
        p.doDeposit(c, depositAmount);

        // withdraw a partial amount
        p.doWithdraw(c, withdrawAmount);

        // rule: refund now returns exactly deposit - withdraw
        p.doRefund(c);
        assertEq(p.received(), depositAmount - withdrawAmount,
            "refund must pay deposit minus withdrawn amount");
    }
}

contract Probe {
    uint256 public received;

    function doDeposit(Wallet c, uint256 amt) external payable {
        c.deposit{value: amt}();
    }

    function doWithdraw(Wallet c, uint256 amt) external {
        c.withdraw(amt);
    }

    function doRefund(Wallet c) external {
        uint256 before = address(this).balance;
        c.refund();
        received = address(this).balance - before;
    }

    receive() external payable {}
}
